function validate([s, goal]) {
  if (typeof s !== 'string' || typeof goal !== 'string') return 's and goal must be strings.';
  if (s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (goal.length < 1 || goal.length > 100) return 'goal needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(goal)) return 'Both strings use lowercase English letters only.';
  return null;
}

