function rotateString(s, goal) {
  if (s.length !== goal.length) {
    return false;
  }
  const text = s + s;
  const lps = new Array(goal.length).fill(0);
  let length = 0;
  for (let i = 1; i < goal.length; i++) {
    while (length > 0 && goal[i] !== goal[length]) {
      length = lps[length - 1];
    }
    if (goal[i] === goal[length]) {
      length++;
    }
    lps[i] = length;
  }
  let matched = 0;
  for (let i = 0; i < text.length; i++) {
    while (matched > 0 && text[i] !== goal[matched]) {
      matched = lps[matched - 1];
    }
    if (text[i] === goal[matched]) {
      matched++;
    }
    if (matched === goal.length) {
      return true;
    }
  }
  return false;
}

