function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  const pool = size === 'large' && rand() < 0.5 ? 'abcdefghijklmnopqrstuvwxyz' : (rand() < 0.7 ? 'ab' : 'abc');
  const pick = () => pool[Math.floor(rand() * pool.length)];
  let s = '';
  if (rand() < 0.4) {
    const period = 1 + Math.floor(rand() * 4);
    let unit = '';
    for (let i = 0; i < period; i++) unit += pick();
    s = unit.repeat(Math.ceil(n / period)).slice(0, n);
  } else {
    for (let i = 0; i < n; i++) s += pick();
  }
  const shift = Math.floor(rand() * n);
  let goal = s.slice(shift) + s.slice(0, shift);
  const mode = rand();
  if (mode < 0.3) {
    const i = Math.floor(rand() * n);
    goal = goal.slice(0, i) + pick() + goal.slice(i + 1);
  } else if (mode < 0.45 && n > 1) {
    const i = Math.floor(rand() * (n - 1));
    goal = goal.slice(0, i) + goal[i + 1] + goal[i] + goal.slice(i + 2);
  } else if (mode < 0.55) {
    if (n > 1 && rand() < 0.5) goal = goal.slice(1);
    else if (n < 100) goal = goal + pick();
  }
  return [s, goal];
}
